      "Deadlines that stay in view": "{count} दृश्य में रहने वाली समय सीमा",
      "Every record carries its own deadline with clear emphasis as it approaches — nothing hides in a cell.": "प्रत्येक रिकॉर्ड में अपनी समय सीमा होती है जो स्पष्ट रूप से बढ़ती है — कोई भी चीज़ सेल में छिपी नहीं होती है।",
      "Documents attached to the application": "आवेदन से जुड़े दस्तावेज़",
      "Transcripts, résumés, letters and portfolios live on the record they belong to, tracked as a simple checklist.": "लिपियों, रिज्यूमे, पत्र और पोर्टफोलियो अपने रिकॉर्ड पर रहते हैं, जो एक सरल चेकलिस्ट के रूप में ट्रैक किए जाते हैं।",
      "A next action, always": "एक अगली कार्रवाई, हमेशा",
      "Each application names the single next step, so you always know what to do without re-reading everything.": "प्रत्येक आवेदन एकल अगले चरण का नाम देता है, ताकि आपको बिना सब कुछ फिर से पढ़े पता चले कि क्या करना है।",
      "Notes, links and context": "नोट्स, लिंक और संदर्भ",
      "The portal link, recruiter thread and your own notes stay together — the memory a spreadsheet row can't hold.": "पोर्टल लिंक, भर्तीकर्ता थ्रेड और आपके अपने नोट्स एक साथ रहते हैं — एक स्प्रेडशीट पंक्ति जो याद नहीं रख सकती",
      "Paste the source": "स्रोत चिपकाएं",
      "Add a link to a university or job posting — start from text you already have.": "एक विश्वविद्यालय या नौकरी पोस्टिंग के लिए एक लिंक जोड़ें — जो पाठ आप पहले से ही रखते हैं",
      "We draft the details": "विवरण तैयार करते हैं",
      "Applume extracts and fills the key fields, so you don't have to.": "Applume महत्वपूर्ण क्षेत्रों को निकालता है और भरता है, इसलिए आपको नहीं करना होगा",
      "You review and save": "आप समीक्षा करते हैं और सेव करते हैं",
      "Confirm, adjust if needed, and add what matters. Nothing is stored without your review.": "पुष्टि करें, यदि आवश्यक हो तो समायोजित करें, और जो महत्वपूर्ण है उसे जोड़ें। आपकी समीक्षा के बिना कुछ भी संग्रहीत नहीं किया जाता है",
      "Does it work for both university and job applications?": "क्या यह विश्वविद्यालय और नौकरी दोनों आवेदनों के लिए काम करता है?",
      "Yes. The same structure tracks admissions and job searches — the labels adapt to each (program vs role, transcript vs résumé, admissions portal vs job listing).": "हाँ। एक ही संरचना प्रवेश और नौकरी खोजों को ट्रैक करती है — लेबल प्रत्येक (कार्यक्रम बनाम भूमिका, प्रतिलेख बनाम रिज्यूमे, प्रवेश पोर्टल बनाम नौकरी सूची) के लिए अनुकूल हैं",
      "Can I import my current spreadsheet?": "क्या मैं अपनी वर्तमान स्प्रेडशीट आयात कर सकता हूँ?",
      "Yes — import a CSV and map your columns to Applume's fields. Your existing rows become structured records you can build on.": "हाँ — एक सीएसवी आयात करें और अपने कॉलम को Applume के क्षेत्रों के साथ मैप करें। आपकी मौजूदा पंक्तियाँ संरचित रिकॉर्ड बन जाती हैं जिन पर आप निर्माण कर सकते हैं",
      "Is my data private?": "क्या मेरा डेटा निजी है?",
      "Your applications are private to your account. Nothing is public unless you deliberately share a read-only link.": "आपके आवेदन आपके खाते के लिए निजी हैं। कुछ भी सार्वजनिक नहीं है जब तक आप जानबूझकर एक केवल-पढ़ने योग्य लिंक साझा नहीं करते हैं",
      "Can I get my data out?": "क्या मैं अपना डेटा बाहर निकाल सकता हूँ?",
      "Yes — export your applications to CSV or JSON at any time. Your records are yours to keep.": "हाँ — अपने आवेदनों को किसी भी समय सीएसवी या जेएसओएन में निर्यात करें। आपके रिकॉर्ड आपके रखने के लिए हैं",
      "Do I need a credit card to start?": "क्या शुरू करने के लिए मुझे क्रेडिट कार्ड की आवश्यकता है?",
      "No. You can start tracking for free without a credit card.": "नहीं। आप क्रेडिट कार्ड के बिना मुफ्त में ट्रैकिंग शुरू कर सकते हैं",
      "Portal link saved": "पोर्टल लिंक सेव किया गया",
      FAQ: "आम प्रश्न",
