      "A spreadsheet remembers the row.": "एक स्प्रेडशीट पंक्ति को याद रखती है।",
      "A spreadsheet row": "एक स्प्रेडशीट पंक्ति",
      "An Applume record": "एक Applume रिकॉर्ड",
