      "Applications are private to your account. Export or delete anytime — nothing is visible to anyone else unless you share a link yourself.": "आवेदन आपके खाते के लिए निजी हैं। कभी भी निर्यात या हटाएं — जब तक आप स्वयं लिंक साझा नहीं करते हैं, किसी और के लिए कुछ भी दिखाई नहीं देता है।",
