      "The structure never changes — only the words do. Switch a record between a university application and a job application and the labels follow.": "संरचना कभी नहीं बदलती — केवल शब्द बदलते हैं। एक रिकॉर्ड को विश्वविद्यालय के आवेदन और नौकरी के आवेदन के बीच स्विच करें और लेबल इसका पालन करते हैं।",
      "Track deadlines, documents, notes, links and next steps — without maintaining another spreadsheet.": "समय सीमा, दस्तावेज़, नोट्स, लिंक और अगले चरणों को ट्रैक करें — किसी अन्य स्प्रेडशीट को बनाए रखने के बिना।",
