      "Deadlines that stay in view": "Plazos que permanecen a la vista",
      "Every record carries its own deadline with clear emphasis as it approaches — nothing hides in a cell.": "Cada registro lleva su propio plazo con énfasis claro a medida que se acerca — nada se esconde en una celda.",
      "Documents attached to the application": "Documentos adjuntos a la solicitud",
      "Transcripts, résumés, letters and portfolios live on the record they belong to, tracked as a simple checklist.": "Transcripciones, currículos, cartas y portafolios viven en el registro al que pertenecen, rastreados como una lista de verificación simple.",
      "A next action, always": "Una próxima acción, siempre",
      "Each application names the single next step, so you always know what to do without re-reading everything.": "Cada solicitud nombra el siguiente paso, así que siempre sabes qué hacer sin volver a leer todo.",
      "Notes, links and context": "Notas, enlaces y contexto",
      "The portal link, recruiter thread and your own notes stay together — the memory a spreadsheet row can't hold.": "El enlace del portal, el hilo del reclutador y tus propias notas permanecen juntos — la memoria que una fila de hoja de cálculo no puede contener.",
      "Paste the source": "Pegar la fuente",
      "Add a link to a university or job posting — start from text you already have.": "Agregar un enlace a una universidad o anuncio de trabajo — comienza desde el texto que ya tienes.",
      "We draft the details": "Redactamos los detalles",
      "Applume extracts and fills the key fields, so you don't have to.": "Applume extrae y rellena los campos clave, así que no tienes que hacerlo.",
      "You review and save": "Revisas y guardas",
      "Confirm, adjust if needed, and add what matters. Nothing is stored without your review.": "Confirma, ajusta si es necesario y agrega lo que importa. Nada se almacena sin tu revisión.",
      "Does it work for both university and job applications?": "¿Funciona para solicitudes de universidad y trabajo?",
      "Yes. The same structure tracks admissions and job searches — the labels adapt to each (program vs role, transcript vs résumé, admissions portal vs job listing).": "Sí. La misma estructura rastrea las admisiones y las búsquedas de trabajo — las etiquetas se adaptan a cada una (programa vs función, transcripción vs currículum, portal de admisiones vs lista de trabajo).",
      "Can I import my current spreadsheet?": "¿Puedo importar mi hoja de cálculo actual?",
      "Yes — import a CSV and map your columns to Applume's fields. Your existing rows become structured records you can build on.": "Sí — importa un CSV y asigna tus columnas a los campos de Applume. Tus filas existentes se convierten en registros estructurados sobre los que puedes construir.",
      "Is my data private?": "¿Es privada mi información?",
      "Your applications are private to your account. Nothing is public unless you deliberately share a read-only link.": "Tus solicitudes son privadas para tu cuenta. Nada es público a menos que compartas deliberadamente un enlace de solo lectura.",
      "Can I get my data out?": "¿Puedo obtener mi información?",
      "Yes — export your applications to CSV or JSON at any time. Your records are yours to keep.": "Sí — exporta tus solicitudes a CSV o JSON en cualquier momento. Tus registros son tuyos para conservar.",
      "Do I need a credit card to start?": "¿Necesito una tarjeta de crédito para empezar?",
      "No. You can start tracking for free without a credit card.": "No. Puedes empezar a rastrear de forma gratuita sin una tarjeta de crédito.",
