      "Transcripts, résumés, letters and portfolios live on the record they belong to, tracked as a simple checklist.": "النصوص، السير الذاتية، الرسائل والمحفظة تعيش على السجل الذي تنتمي إليه، وتتم تتبعها كقائمة بسيطة.",
