      "The portal link, recruiter thread and your own notes stay together — the memory a spreadsheet row can't hold.": "يبقى رابط البوابة وخط Thread للتوظيف وملاحظاتك الخاصة معًا - الذاكرة التي لا يستطيع صف في جدول البيانات احتواؤها.",
