      "Applume extracts and fills the key fields, so you don't have to.": "يستخرج Applume ويملأ الحقول الرئيسية ، لذلك لا تحتاج إلى ذلك.",
      "You review and save": "مراجعة و حفظ",
      "Confirm, adjust if needed, and add what matters. Nothing is stored without your review.": "أكد ، وضبط إذا لزم الأمر ، وأضف ما يهم. لا يتم تخزين أي شيء بدون مراجعتك.",
      "Does it work for both university and job applications?": "هل يعمل للتقديمات الجامعية والوظيفية؟",
      "Yes. The same structure tracks admissions and job searches — the labels adapt to each (program vs role, transcript vs résumé, admissions portal vs job listing).": "نعم. نفس الهيكل يتبع القبول والبحث عن عمل - التسميات تتبع كل منها (البرنامج مقابل الدور ، النص مقابل السيرة الذاتية ، بوابة القبول مقابل قائمة العمل).",
      "Can I import my current spreadsheet?": "هل يمكنني استيراد جدولي الحالي؟",
      "Yes — import a CSV and map your columns to Applume's fields. Your existing rows become structured records you can build on.": "نعم - استيراد CSV وربط أعمدة جدولك بحقول Applume. تصبح صفوفك الحالية سجلات منظمة يمكنك بناؤها عليها.",
      "Is my data private?": "هل بياناتي خاصة؟",
