      "Can I get my data out?": "هل يمكنني الحصول على بياناتي؟",
      "Yes — export your applications to CSV or JSON at any time. Your records are yours to keep.": "نعم - استخرج تطبيقاتك إلى CSV أو JSON في أي وقت. سجلاتك ملك لك للاحتفاظ بها.",
      "Do I need a credit card to start?": "هل أحتاج إلى بطاقة ائتمان للبدء؟",
