      "Every record carries its own deadline with clear emphasis as it approaches — nothing hides in a cell.": "Chaque enregistrement comporte sa propre date limite avec une emphase claire à mesure qu'elle approche — rien ne se cache dans une cellule.",
      "Documents attached to the application": "Documents joints à la candidature",
      "Transcripts, résumés, letters and portfolios live on the record they belong to, tracked as a simple checklist.": "Les transcrits, les résumés, les lettres et les portfolios vivent sur l'enregistrement auquel ils appartiennent, suivis sous forme de liste de contrôle simple.",
