      "Notes, links and context": "Notes, liens et contexte",
      "The portal link, recruiter thread and your own notes stay together — the memory a spreadsheet row can't hold.": "Le lien du portail, le fil du recruteur et vos propres notes restent ensemble — la mémoire qu'une ligne de feuille de calcul ne peut pas contenir.",
      "Paste the source": "Coller la source",
