      "You review and save": "Vous révisez et enregistrez",
      "Confirm, adjust if needed, and add what matters. Nothing is stored without your review.": "Confirmez, ajustez si nécessaire, et ajoutez ce qui compte. Rien n'est stocké sans votre révision.",
      "Does it work for both university and job applications?": "Fonctionne-t-il pour les candidatures universitaires et professionnelles ?",
      "Yes. The same structure tracks admissions and job searches — the labels adapt to each (program vs role, transcript vs résumé, admissions portal vs job listing).": "Oui. La même structure suit les admissions et les recherches d'emploi — les étiquettes s'adaptent à chacune (programme vs rôle, transcrit vs résumé, portail d'admission vs liste d'emplois).",
      "Can I import my current spreadsheet?": "Puis-je importer ma feuille de calcul actuelle ?",
      "Yes — import a CSV and map your columns to Applume's fields. Your existing rows become structured records you can build on.": "Oui — importez un CSV et mappez vos colonnes aux champs d'Applume. Vos lignes existantes deviennent des enregistrements structurés sur lesquels vous pouvez vous appuyer.",
      "Is my data private?": "Mes données sont-elles privées ?",
