      "The portal link, recruiter thread and your own notes stay together — the memory a spreadsheet row can't hold.": "পোর্টাল লিঙ্ক, রিক্রুটার থ্রেড এবং আপনার নিজস্ব নোটগুলি একসাথে থাকে - একটি স্প্রেডশীট সারি ধরে রাখতে পারে না এমন স্মৃতি।",
      "Paste the source": "উত্স পেস্ট করুন",
