      "You review and save": "আপনি পর্যালোচনা করুন এবং সংরক্ষণ করুন",
      "Confirm, adjust if needed, and add what matters. Nothing is stored without your review.": "নিশ্চিত করুন, প্রয়োজন হলে সামঞ্জস্য করুন এবং যা গুরুত্বপূর্ণ তা যোগ করুন। আপনার পর্যালোচনা ছাড়া কিছুই সংরক্ষণ করা হয় না।",
      "Does it work for both university and job applications?": "এটি বিশ্ববিদ্যালয় এবং চাকরির উভয় আবেদনের জন্য কাজ করে?",
      "Yes. The same structure tracks admissions and job searches — the labels adapt to each (program vs role, transcript vs résumé, admissions portal vs job listing).": "হ্যাঁ। একই কাঠামো ভর্তি এবং চাকরি সন্ধানগুলি ট্র্যাক করে - লেবেলগুলি প্রতিটিতে (প্রোগ্রাম বনাম ভূমিকা, ট্রান্সক্রিপ্ট বনাম রিজুমে, ভর্তি পোর্টাল বনাম চাকরি তালিকা) অভিযোজিত হয়।",
      "Can I import my current spreadsheet?": "আমি কি আমার বর্তমান স্প্রেডশীট আমদানি করতে পারি?",
      "Yes — import a CSV and map your columns to Applume's fields. Your existing rows become structured records you can build on.": "হ্যাঁ - একটি CSV আমদানি করুন এবং আপনার কলামগুলিকে Applume এর ক্ষেত্রগুলিতে ম্যাপ করুন। আপনার বিদ্যমান সারিগুলি গঠনমূলক রেকর্ডে পরিণত হয় যা আপনি তৈরি করতে পারেন।",
      "Is my data private?": "আমার ডেটা ব্যক্তিগত?",
      "Your applications are private to your account. Nothing is public unless you deliberately share a read-only link.": "আপনার আবেদনগুলি আপনার অ্যাকাউন্টে ব্যক্তিগত। আপনি ইচ্ছাকৃতভাবে একটি রিড-অনলি লিঙ্ক ভাগ না করা পর্যন্ত কিছুই পাবলিক নয়।",
      "Can I get my data out?": "আমি কি আমার ডেটা বের করতে পারি?",
      "Yes — export your applications to CSV or JSON at any time. Your records are yours to keep.": "হ্যাঁ - যেকোনো সময় আপনার আবেদনগুলিকে CSV বা JSON এ রফতানি করুন। আপনার রেকর্ডগুলি আপনার রাখার জন্য।",
      "Do I need a credit card to start?": "শুরু করতে আমার একটি ক্রেডিট কার্ড দরকার?",
      "No. You can start tracking for free without a credit card.": "না। আপনি একটি ক্রেডিট কার্ড ছাড়াই বিনামূল্যে ট্র্যাকিং শুরু করতে পারেন।",
