      "You already have {name} tracked as a {type} — currently {status}. You can still save this as a separate entry.": "آپ کے پاس پہلے ہی {name} {type} کے طور پر ٹریک کیا گیا ہے — فی الحال {status}۔ آپ اب بھی اسے الگ انٹری کے طور پر بچا سکتے ہیں.",
