      "Capturing why helps you spot patterns and adjust the next applications.": "کیوں کی ریکارڈنگ آپ کو نمونے کو پہچاننے اور اگلی درخواستوں کو ایڈجسٹ کرنے میں مدد کرتی ہے۔",
      "A quick note keeps the context when this application comes back around.": "ایک تیزی سے نوٹ اس درخواست کے بارے میں سیاق و سباق کو برقرار رکھتا ہے جب یہ دوبارہ آتا ہے۔",
