      "Deadlines that stay in view": "ڈیڈ لائنز جو نظر میں رہتے ہیں",
      "Every record carries its own deadline with clear emphasis as it approaches — nothing hides in a cell.": "ہر ریکارڈ اپنی ڈیڈ لائن لے کر آتا ہے جس پر واضح زور دیا جاتا ہے جب وہ قریب آتا ہے — کوئی بھی چیز سیل میں چھپی نہیں ہوتی۔",
      "Documents attached to the application": "اپلی کیشن سے منسلک دستاویزات",
      "Transcripts, résumés, letters and portfolios live on the record they belong to, tracked as a simple checklist.": "ٹرانسکرپٹ، ریزومے، خطوط اور پورٹ فولیوز اپنے ریکارڈ پر رہتے ہیں، ایک سادہ چیک لسٹ کے طور پر ٹریک کیے جاتے ہیں۔",
