      "Each application names the single next step, so you always know what to do without re-reading everything.": "ہر ایپلیکیشن میں اگلا قدم بتایا جاتا ہے، تاکہ آپ کو ہر چیز کو دوبارہ پڑھنے کی ضرورت نہیں ہو۔",
      "Notes, links and context": "نوٹس، لنکس اور سیاق و سباق",
      "The portal link, recruiter thread and your own notes stay together — the memory a spreadsheet row can't hold.": "پورٹل لنک، ریکروٹر تھریڈ اور آپ کے اپنے نوٹس ایک ساتھ رہتے ہیں — ایک اسپریڈ شیٹ کے سیل میں رکھی جانے والی یادداشت۔",
      "Paste the source": "ماخذ کو پیسٹ کریں",
      "Add a link to a university or job posting — start from text you already have.": "ایک یونیورسٹی یا نوکری کی پوسٹنگ کے لنک شامل کریں — اپنے پاس موجود ٹیکسٹ سے شروع کریں۔",
      "We draft the details": "ہم تفصیلات تیار کرتے ہیں",
      "Applume extracts and fills the key fields, so you don't have to.": "Applume اہم فیلڈز کو نکالتا ہے اور ان کو بھرتا ہے، تاکہ آپ کو خود سے کرنے کی ضرورت نہیں۔",
      "You review and save": "آپ جائزہ لیتے ہیں اور بچاتے ہیں",
      "Confirm, adjust if needed, and add what matters. Nothing is stored without your review.": "تصدیق کریں، ضرورت پڑنے پر ایڈجسٹ کریں، اور جو ضروری ہے وہ شامل کریں۔ آپ کے جائزے کے بغیر کوئی بھی چیز محفوظ نہیں کی جاتی۔",
      "Does it work for both university and job applications?": "کیا یہ یونیورسٹی اور نوکری دونوں کی ایپلیکیشنز کے لیے کام کرتا ہے؟",
      "Yes. The same structure tracks admissions and job searches — the labels adapt to each (program vs role, transcript vs résumé, admissions portal vs job listing).": "جی ہاں۔ ایک ہی ڈھانچہ داخلہ اور نوکری کی تلاش دونوں کو ٹریک کرتا ہے — لیبلز ہر ایک (پروگرام بمقابلہ رول، ٹرانسکرپٹ بمقابلہ ریزومے، داخلہ پورٹل بمقابلہ نوکری کی فہرست) کے لیے ایڈجسٹ ہوتے ہیں۔",
      "Can I import my current spreadsheet?": "کیا میں اپنی موجودہ اسپریڈ شیٹ کو درآمد کر سکتا ہوں؟",
      "Yes — import a CSV and map your columns to Applume's fields. Your existing rows become structured records you can build on.": "جی ہاں — ایک CSV کو درآمد کریں اور اپنے کالمز کو Applume کے فیلڈز سے منسلک کریں۔ آپ کی موجودہ سطریں ساخت یافتہ ریکارڈ بن جاتی ہیں جن پر آپ تعمیر کر سکتے ہیں۔",
      "Is my data private?": "کیا میرا ڈیٹا نجی ہے؟",
      "Your applications are private to your account. Nothing is public unless you deliberately share a read-only link.": "آپ کی ایپلیکیشنز آپ کے اکاؤنٹ کے لیے نجی ہیں۔ کوئی بھی چیز عوامی نہیں ہے جب تک کہ آپ جان بوجھ کر ایک ریڈ اونلی لنک شیئر نہ کریں۔",
      "Can I get my data out?": "کیا میں اپنا ڈیٹا باہر لے سکتا ہوں؟",
      "Yes — export your applications to CSV or JSON at any time. Your records are yours to keep.": "جی ہاں — اپنی ایپلیکیشنز کو CSV یا JSON میں کسی بھی وقت برآمد کریں۔ آپ کے ریکارڈ آپ کے پاس رکھنے کے لیے ہیں۔",
      "Do I need a credit card to start?": "کیا مجھے شروع کرنے کے لیے کریڈٹ کارڈ کی ضرورت ہے؟",
      "No. You can start tracking for free without a credit card.": "نہیں۔ آپ کریڈٹ کارڈ کے بغیر مفت میں ٹریکنگ شروع کر سکتے ہیں۔",
      "Portal link saved": "پورٹل لنک محفوظ شدہ",
      FAQ: "آئی کیو",
      "A few things people ask before moving their applications over.": "لوگ اپنے اپلی کیشنز کو منتقل کرنے سے پہلے کچھ چیزیں پوچھتے ہیں۔",
      "A spreadsheet remembers the row.": "ایک اسپریڈ شیٹ سطر کو یاد رکھتی ہے۔",
