      "Applications are private to your account. Export or delete anytime — nothing is visible to anyone else unless you share a link yourself.": "اپلی کیشنز آپ کے اکاؤنٹ کے لئے نجی ہیں۔ جب چاہیں ایکسپورٹ یا ڈیلیٹ کریں — اگر آپ خود سے لنک شیئر نہ کریں تو کسی اور کو کچھ بھی نظر نہیں آئے گا۔",
